#!/usr/bin/env python3
from pathlib import Path
import re,sys
# Only digestive and reproductive FAIL rows. WVS/oral/aboral/nervous protected. Five provisional absent figures not created.
def F(pid,title,aria,body,legend):
 return f'''<figure class="sys-fig v188-pencil-plate v188-asterias-remediation" data-v188-plate="{pid}"><figcaption><strong>{title}</strong><span class="ta-explain" lang="ta">TERMINOLOGY REVIEW PENDING</span></figcaption><svg class="sys-svg" viewBox="0 0 760 500" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg"><rect width="760" height="500" fill="#fffefa"/><g fill="none" stroke="#303030" stroke-linecap="round" stroke-linejoin="round">{body}</g></svg><div class="v188-figure-legend" data-legend-en="{legend}" data-legend-ta="TERMINOLOGY REVIEW PENDING"></div></figure>'''
DIG=F('ASTERIAS-DIG-R1','Asterias — digestive system','Asterias digestive system showing mouth, short oesophagus, eversible cardiac stomach, pyloric stomach, pyloric caeca in arms, intestine, rectum and aboral anus.',r'''<path d="M380 45L430 165L565 145L460 235L525 390L395 295L275 400L320 240L185 155L335 170Z" stroke-width="2"/><circle cx="380" cy="260" r="8"/><path d="M380 252V230" stroke-width="4"/><ellipse cx="380" cy="205" rx="58" ry="42" stroke-width="3"/><ellipse cx="380" cy="145" rx="42" ry="28" stroke-width="3"/><path d="M380 117V85" stroke-width="3"/><circle cx="380" cy="75" r="6"/><path d="M350 140Q295 105 245 95M410 140Q465 105 515 95M350 150Q285 215 245 260M410 150Q475 215 520 265M380 125Q380 85 380 75" stroke-width="5"/><g stroke-width="1"><path d="M380 260L650 260"/><path d="M380 235L650 220"/><path d="M380 205L650 180"/><path d="M380 145L650 135"/><path d="M245 95L70 75"/><path d="M380 75L650 75"/></g><g fill="#222" stroke="none" font-family="sans-serif" font-size="12"><text x="660" y="265">Mouth</text><text x="660" y="225">Short oesophagus</text><text x="660" y="185">Cardiac stomach — eversible</text><text x="660" y="140">Pyloric stomach</text><text x="10" y="70">Pyloric caeca extend into arms</text><text x="660" y="80">Intestine → rectum → aboral anus</text></g>''','Mouth → short oesophagus → eversible cardiac stomach → pyloric stomach → pyloric caeca; intestine → rectum → aboral anus')
REP=F('ASTERIAS-REP-R1','Asterias — reproductive organisation','Asterias reproductive plate showing separate sexes, paired gonads in interradial arm bases, gonopores, external gamete release and external fertilisation without claiming sexual dimorphism.',r'''<path d="M380 45L430 165L565 145L460 235L525 390L395 295L275 400L320 240L185 155L335 170Z" stroke-width="2"/><ellipse cx="400" cy="125" rx="18" ry="42"/><ellipse cx="470" cy="195" rx="42" ry="18"/><ellipse cx="440" cy="300" rx="38" ry="18"/><ellipse cx="320" cy="300" rx="38" ry="18"/><ellipse cx="285" cy="195" rx="42" ry="18"/><g fill="#303030" stroke="none"><circle cx="405" cy="82" r="5"/><circle cx="520" cy="175" r="5"/><circle cx="475" cy="340" r="5"/><circle cx="285" cy="340" r="5"/><circle cx="235" cy="175" r="5"/></g><g stroke-width="1"><path d="M400 125L610 80"/><path d="M405 82L620 140"/></g><path d="M610 250q25-25 50 0M610 270q25 25 50 0" stroke-width="1.5"/><g fill="#222" stroke="none" font-family="sans-serif" font-size="12"><text x="560" y="70">Paired gonads in interradial regions of arms</text><text x="560" y="135">Gonopores open aborally near arm bases</text><text x="525" y="310">Separate sexes (dioecious); no marked sexual dimorphism</text><text x="510" y="350">Gametes released to seawater → external fertilisation</text></g>''','Asterias is dioecious; sexes are not externally dimorphic; paired gonads occupy interradial arm regions; gonopores release gametes aborally; fertilisation is external')
def repl(s,old,new):
 p=rf'<figure[^>]*data-v188-plate="{re.escape(old)}"[\s\S]*?</figure>';o,n=re.subn(p,new,s,count=1)
 if n!=1:raise SystemExit(f'{old}: {n}')
 return o
def main(root):
 ps=[Path(root)/'academic_payload/index.html',Path(root)/'app/src/main/assets/www/index.html']
 for p in ps:
  s=p.read_text(encoding='utf-8');s=repl(s,'asterias-digestive',DIG);s=repl(s,'asterias-reproductive',REP);p.write_text(s,encoding='utf-8')
 if ps[0].read_bytes()!=ps[1].read_bytes():raise SystemExit('payload copies diverged')
 print('Asterias digestive/reproductive corrected; WVS and provisional absent figures untouched; BUILD_ELIGIBLE=NO')
if __name__=='__main__':main(sys.argv[1] if len(sys.argv)>1 else '.')